function addFiles(list){const existing=new Set(state.files.map(fileKey));Array.from(list).forEach(function(file){const ext=file.name.toLowerCase().split('.').pop();if(['jpg','jpeg','png','pdf'].indexOf(ext)<0){showError(file.name+' 的格式需要使用 JPG、PNG 或 PDF');return}if(file.size>24*1024*1024){showError(file.name+' 超过 24 MB');return}if(!existing.has(fileKey(file))){state.files.push(file);existing.add(fileKey(file))}});renderFiles()}
function renderFiles(){el.fileList.replaceChildren();if(!state.files.length){el.fileList.classList.add('empty');const empty=document.createElement('div');empty.className='empty-files';empty.textContent='已选文件会显示在这里';el.fileList.append(empty)}else{el.fileList.classList.remove('empty');state.files.forEach(function(file,index){const item=document.createElement('div');item.className='file-item';let thumb;if(file.type.indexOf('image/')===0){thumb=document.createElement('img');thumb.src=URL.createObjectURL(file);thumb.alt=''}else{thumb=document.createElement('div');thumb.textContent='PDF'}thumb.className='file-thumb file-icon';const info=document.createElement('div');info.className='file-info';const name=document.createElement('strong');name.textContent=file.name;const size=document.createElement('span');size.textContent=humanSize(file.size);info.append(name,size);const remove=document.createElement('button');remove.className='remove-file';remove.type='button';remove.setAttribute('aria-label','移除 '+file.name);remove.textContent='×';remove.addEventListener('click',function(){state.files.splice(index,1);renderFiles()});item.append(thumb,info,remove);el.fileList.append(item)})}el.scanButton.disabled=!state.files.length||state.scanning;el.metricFiles.textContent=state.files.length}
function filePayload(file){return new Promise(function(resolve,reject){const reader=new FileReader();reader.onload=function(){resolve({name:file.name,data:reader.result})};reader.onerror=function(){reject(new Error('读取 '+file.name+' 失败'))};reader.readAsDataURL(file)})}
