async function submitScan(endpoint,payload,count){setScanning(true,count);try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'扫描任务失败');el.progressBar.style.width='100%';el.statusTitle.textContent='识别完成';el.statusCopy.textContent='任务 '+result.job_id+' 已生成结果，可在下方预览并下载 CSV。';el.metricFiles.textContent=result.file_count;el.metricRows.textContent=result.rows.length;el.metricTime.textContent=result.duration_seconds+'s';renderResults(result)}catch(error){el.progressBar.style.width='0%';el.statusTitle.textContent='任务出错';el.statusCopy.textContent=error.message;el.metricRows.textContent='0';showError(error.message)}finally{setScanning(false,0)}}
function renderResults(result){el.resultsPanel.classList.remove('hidden');el.downloadButton.href=result.download_url;const columns=preferred.filter(function(column){return result.columns.indexOf(column)>=0});const headRow=document.createElement('tr');columns.forEach(function(column){const cell=document.createElement('th');cell.textContent=columnLabels[column]||column;headRow.append(cell)});el.resultTable.querySelector('thead').replaceChildren(headRow);const body=el.resultTable.querySelector('tbody');body.replaceChildren();result.rows.forEach(function(row,index){const tr=document.createElement('tr');columns.forEach(function(column){const cell=document.createElement('td');cell.textContent=row[column]||'';tr.append(cell)});tr.addEventListener('click',function(){selectRow(tr,row)});body.append(tr);if(index===0)selectRow(tr,row)});el.resultsPanel.scrollIntoView({behavior:'smooth',block:'start'})}
