function renderImportResult(result){importEl.result.dataset.importId=result.import_id;const summary=result.summary||{};const types=Object.entries(summary.types||{}).map(function(entry){return entry[0]+' '+entry[1]+' \u9898'}).join('\uff0c');importEl.summary.textContent=(result.name||'试卷')+'；\u5bfc\u5165\u7f16\u53f7 '+result.import_id+'\uff1b\u7ae0\u8282 '+(summary.section_count||0)+' \u4e2a\uff1b\u9898\u76ee '+(summary.question_count||0)+' \u9053\uff1b\u603b\u5206 '+(summary.total_score||0)+' \u5206\uff1b\u9898\u578b\uff1a'+types+'\uff1b\u7b54\u6848 '+(result.answer_count||0)+' \u9879'+(result.answer_missing&&result.answer_missing.length?'\uff1b\u5f85\u8865\u7b54\u6848 '+result.answer_missing.join('\u3001'):'');importEl.sections.replaceChildren();(result.sections||[]).forEach(function(section){const item=document.createElement('div');item.className='import-section-item';const title=document.createElement('strong');title.textContent=section.name||'\u672a\u547d\u540d\u7ae0\u8282';const detail=document.createElement('span');detail.textContent=(section.questions||[]).length+' \u9898\uff0c'+(section.total_score||0)+' \u5206';item.append(title,detail);importEl.sections.append(item)});importEl.download.href=result.normalized_url||'#';importEl.result.classList.remove('hidden');reviewState.importId=result.import_id;loadReviewImports(result.import_id)}
importEl.button.addEventListener('click',async function(){const examText=importEl.examText.value.trim(),answerText=importEl.answerText.value.trim();if(!examText){showError('\u8bf7\u7c98\u8d34\u6216\u9009\u62e9\u8bd5\u5377 JSON');return}importEl.button.disabled=true;importEl.status.textContent='\u6b63\u5728\u89e3\u6790\u3001\u4fee\u590d\u5e76\u6821\u9a8c\u7ed3\u6784\u5316\u8bd5\u5377...';try{const response=await fetch('/api/exam/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:importEl.name.value.trim(),exam_text:examText,answer_text:answerText})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||result.detail||'\u8bd5\u5377\u5bfc\u5165\u5931\u8d25');importEl.status.textContent='\u8bd5\u5377\u548c\u7b54\u6848\u4fe1\u606f\u5bfc\u5165\u5b8c\u6210\u3002';renderImportResult(result)}catch(error){importEl.status.textContent=error.message;showError(error.message)}finally{importEl.button.disabled=false}});
async function deleteExamImport(importId,name){
  if(reviewState.running){showError('批改任务正在运行，请在完成后删除试卷。');return}
  if(importEl.button.disabled){showError('试卷正在导入，请在完成后删除试卷。');return}
  if(importId===reviewState.importId&&!window.platform.confirmSwitch())return;
  if(!window.confirm('确认删除《'+name+'》？删除后将从试卷库移除，已有批改记录保留。'))return;
  try{
    const response=await fetch('/api/exam/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({import_id:importId})});
    const result=await response.json();
    if(!response.ok||!result.ok)throw new Error(result.error||result.detail||'试卷删除失败');
    if(importEl.result.dataset.importId===importId){importEl.result.classList.add('hidden');delete importEl.result.dataset.importId;importEl.download.removeAttribute('href')}
    importEl.status.textContent='已删除试卷：'+name;
    await loadReviewImports(undefined,true);
  }catch(error){showError(error.message)}
}
