function buildImportedScoreMap(payload){const exam=payload&&payload.exam?payload.exam:payload||{};const scores={};(exam.sections||[]).forEach(function(section){(section.questions||[]).forEach(function(question){const ids=(question.question_ids&&question.question_ids.length?question.question_ids:[question.id]).map(String),total=Math.max(0,Number(question.score)||0),explicit=question.score_map||question.sub_scores||{};const explicitValues=ids.map(function(id){return Object.prototype.hasOwnProperty.call(explicit,id)?Number(explicit[id]):NaN});const valid=explicitValues.every(Number.isFinite)&&Math.abs(explicitValues.reduce(function(sum,value){return sum+value},0)-total)<=.01;ids.forEach(function(id,index){scores[id]=valid?explicitValues[index]:total/ids.length})})});return scores}
function applyImportedScores(){reviewState.objective.forEach(function(item){if(item.score===undefined||item.score===null||item.score==='')item.score=reviewState.scoreMap[item.question]||0});reviewState.items.forEach(function(item){if(item.score===undefined||item.score===null||item.score==='')item.score=reviewState.scoreMap[item.question]||0})}
async function loadReviewScoreMap(importId){reviewState.scoreMap={};if(!importId)return;try{const response=await fetch('/imports/'+encodeURIComponent(importId)+'/normalized_exam.json');if(!response.ok)throw new Error('读取试卷分值失败');const imported=await response.json();reviewState.scoreMap=buildImportedScoreMap(imported);applyImportedScores();if(!reviewEl.results.classList.contains('hidden'))renderScoreBoard()}catch(error){reviewEl.status.textContent='试卷分值读取失败：'+error.message}}
