async function loadReviewImports(preferredId,preserveReview=false){try{const response=await fetch('/api/exam/imports');const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'读取已导入试卷失败');const imports=result.imports||[];window.dispatchEvent(new CustomEvent('platform:imports',{detail:imports}));const selected=preferredId||reviewEl.importSelect.value||reviewState.importId;reviewEl.importSelect.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='请选择已导入试卷';reviewEl.importSelect.append(placeholder);imports.forEach(function(entry){const option=document.createElement('option');option.value=entry.import_id;const summary=entry.summary||{};option.textContent=(entry.name||entry.import_id)+' · '+(summary.question_count||0)+'题 · 答案'+(entry.answer_count||0)+'项';reviewEl.importSelect.append(option)});const selectedExists=imports.some(function(entry){return entry.import_id===selected});if(preserveReview&&selectedExists){reviewEl.importSelect.value=selected}else{selectReviewImport(selectedExists?selected:(imports[0]&&imports[0].import_id)||'')}}catch(error){reviewEl.status.textContent=error.message;window.dispatchEvent(new CustomEvent('platform:imports-error',{detail:error.message}));showError(error.message)}}
