async function loadBatchReview(reviewId,showResult=true){if(!reviewId)return;if(showResult&&reviewId!==reviewState.reviewId&&!window.platform.confirmSwitch())return;try{const response=await fetch('/api/review/status?review_id='+encodeURIComponent(reviewId));const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'读取批改结果失败');if(result.import_id&&result.import_id!==reviewState.importId){reviewState.importId=result.import_id;reviewEl.importSelect.value=result.import_id;await loadReviewScoreMap(result.import_id)}renderReview(result,false);if(showResult)window.platform.navigate('results');reviewState.batchLoaded=true;if(result.ai_judgment&&result.ai_judgment.status==='处理中')startReviewPolling()}catch(error){showError(error.message)}}
function renderBatchStatus(batch){window.dispatchEvent(new CustomEvent('platform:batch',{detail:batch}));reviewEl.batchPanel.classList.remove('hidden');const done=(Number(batch.completed)||0)+(Number(batch.failed)||0),total=Number(batch.total)||0;reviewEl.batchSummary.textContent=(batch.phase||batch.status||'处理中')+' · 并发 '+(batch.concurrency||1)+' 份'+(batch.duration_seconds?' · '+batch.duration_seconds+' 秒':'');reviewEl.batchProgress.textContent=done+' / '+total;reviewEl.batchList.replaceChildren();let firstReady='';(batch.reviews||[]).forEach(function(entry,index){const button=document.createElement('button');button.type='button';button.className='batch-review-card '+(entry.status==='失败'?'failed':entry.review_id?'':'processing')+(entry.review_id===reviewState.reviewId?' selected':'');const title=document.createElement('strong');title.textContent=entry.label||('第'+(index+1)+'份');const detail=document.createElement('span');if(entry.status==='失败'){detail.textContent='失败：'+(entry.error||'处理异常')}else if(entry.review_id){const score=entry.score_summary||{},ai=entry.ai_judgment||{};detail.textContent=(entry.student_name?entry.student_name+' · ':'')+(entry.student_id||'学号待识别')+' · '+formatScore(score.total_score)+' / '+formatScore(score.possible_score)+' · '+(ai.status||'规则完成');if(!firstReady)firstReady=entry.review_id;button.addEventListener('click',function(){loadBatchReview(entry.review_id)})}else{detail.textContent=entry.status||'等待中'}button.append(title,detail);reviewEl.batchList.append(button)});if(firstReady&&!reviewState.batchLoaded)loadBatchReview(firstReady,false)}
async function pollBatchStatus(){if(!reviewState.batchId||reviewState.batchBusy)return;reviewState.batchBusy=true;try{const response=await fetch('/api/review/batch/status?batch_id='+encodeURIComponent(reviewState.batchId));const batch=await response.json();if(!response.ok||!batch.ok)throw new Error(batch.error||'获取批量进度失败');renderBatchStatus(batch);const finished=(Number(batch.completed)||0)+(Number(batch.failed)||0)>=Number(batch.total||0);if(finished&&Number(batch.ai_processing||0)===0){stopBatchPolling();reviewState.running=false;updateReviewButton();reviewEl.status.textContent=batch.message||'批量批改完成。'}else{reviewEl.status.textContent=batch.message||('正在并发批改 '+(batch.total||0)+' 份答题卡')}}catch(error){stopBatchPolling();reviewState.running=false;updateReviewButton();reviewEl.status.textContent=error.message;showError(error.message)}finally{reviewState.batchBusy=false}}
