function updateAiProgress(ai){const running=ai.status==='处理中';const total=Math.max(0,Number(ai.group_count)||0);const done=Math.min(total,Math.max(0,Number(ai.completed_groups)||0));const visible=running||total>0||reviewState.aiPanelPinned||Boolean(reviewState.aiStartedAt&&ai.status&&ai.status!=='未配置');reviewEl.aiProgress.classList.toggle('hidden',!visible);if(!visible){resetAiProgress(false);return}if(running&&!reviewState.aiStartedAt)reviewState.aiStartedAt=Date.now();if(running&&!reviewState.elapsedTimer){reviewState.elapsedTimer=setInterval(updateAiElapsed,1000)}if(!running&&reviewState.elapsedTimer){clearInterval(reviewState.elapsedTimer);reviewState.elapsedTimer=null}updateAiElapsed();reviewEl.aiProgress.classList.toggle('preparing',running&&total===0);reviewEl.aiTrack.setAttribute('aria-valuemax',String(Math.max(1,total)));reviewEl.aiTrack.setAttribute('aria-valuenow',String(done));reviewEl.aiFill.style.width=(total?Math.round(100*done/total):0)+'%';const label=ai.current_group?'正在审核大题 '+ai.current_group+' · ':'';reviewEl.aiProgressText.textContent=running?(total?label+'已完成 '+done+'/'+total+' 组':'正在准备大题分组...'):(ai.status||'已完成')+' · '+(ai.message||'已完成 '+done+'/'+total+' 组');reviewEl.aiButton.disabled=running;reviewEl.aiButton.querySelector('span').textContent=running?'AI审核进行中…':'AI判断手写内容'}
