function calculateLocalScore(){let objective=0,objectivePossible=0,text=0,textPossible=0,pending=0,pendingCount=0;const pass=new Set(['自动通过','通过']),fail=new Set(['不通过']);reviewState.objective.forEach(function(item){const score=Number(item.score)||0,status=objectiveLocalStatus(item);objectivePossible+=score;if(pass.has(status))objective+=score;else if(!fail.has(status)){pending+=score;pendingCount++}});reviewState.items.forEach(function(item){const score=Number(item.score)||0,status=textLocalStatus(item);textPossible+=score;if(pass.has(status))text+=score;else if(!fail.has(status)){pending+=score;pendingCount++}});const localPossible=objectivePossible+textPossible;if(localPossible===0&&Number(reviewState.scoreSummary.possible_score)>0)return Object.assign({},reviewState.scoreSummary,{pending_count:1});return{total_score:objective+text,possible_score:localPossible,objective_score:objective,objective_possible:objectivePossible,text_score:text,text_possible:textPossible,pending_score:pending,pending_count:pendingCount}}
function renderScoreBoard(){const score=calculateLocalScore();window.dispatchEvent(new CustomEvent('platform:score',{detail:score}));reviewEl.totalScore.textContent=formatScore(score.total_score)+' / '+formatScore(score.possible_score);reviewEl.objectiveScore.textContent=formatScore(score.objective_score)+' / '+formatScore(score.objective_possible);reviewEl.textScore.textContent=formatScore(score.text_score)+' / '+formatScore(score.text_possible);reviewEl.pendingScore.textContent=formatScore(score.pending_score)+' 分';reviewEl.confirmGrade.disabled=reviewState.running||!reviewState.reviewId||score.pending_count>0||reviewState.gradeConfirmed;reviewEl.confirmGrade.firstElementChild.textContent=reviewState.gradeConfirmed?'成绩已确认':'确认成绩';reviewEl.save.disabled=reviewState.gradeConfirmed||reviewState.running}
function objectiveNeedsReview(item){return item.auto_status!=='自动通过'||Boolean(item.override_answer)||Boolean(item.manual_status)}
function objectiveRecognitionLabel(item){const warning=String(item.recognition_warning||'');if(warning.includes('多处填涂'))return '多处填涂';if(warning)return item.recognized_label||'无法确定';if(item.recognized)return item.recognized;if(item.recognized_label)return item.recognized_label;return '空白'}
