  reviewEl.objectiveSummary.textContent='共 '+(summary.total||reviewState.objective.length)+' 题 · 自动通过 '+(summary.auto_pass||0)+' 题 · 人工已复核 '+(summary.reviewed||0)+' 题 · 最终通过 '+(summary.final_pass||0)+' 题';
