function stopReviewPolling(){if(reviewState.pollTimer){clearInterval(reviewState.pollTimer);reviewState.pollTimer=null}}
async function pollReviewStatus(){if(!reviewState.reviewId||reviewState.pollBusy)return;reviewState.pollBusy=true;try{const response=await fetch('/api/review/status?review_id='+encodeURIComponent(reviewState.reviewId));const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'获取AI状态失败');reviewState.pollErrors=0;const ai=result.ai_judgment||{};updateAiProgress(ai);if(ai.status==='处理中'){reviewEl.status.textContent=ai.message||'AI正在审核手写内容';return}stopReviewPolling();renderReview(result,false);reviewEl.status.textContent=ai.status==='已完成'?'AI判断完成，请逐题确认结果。':ai.status==='部分完成'?'AI部分完成：'+(ai.message||'请复核剩余题目'):ai.status==='异常'?'AI处理提示：'+(ai.message||'请稍后重试'):ai.status==='未配置'?'AI接口等待配置。':'OCR与规则初判完成。'}catch(error){reviewState.pollErrors+=1;reviewEl.status.textContent='正在重试获取AI进度：'+error.message;if(reviewState.pollErrors===1)showError(error.message)}finally{reviewState.pollBusy=false}}
function startReviewPolling(){stopReviewPolling();reviewState.pollTimer=setInterval(pollReviewStatus,2000);pollReviewStatus()}
async function requestAiJudgment(){if(!reviewState.reviewId)return;reviewState.aiPanelPinned=true;reviewState.aiStartedAt=Date.now();updateAiProgress({status:'处理中',group_count:0,completed_groups:0});reviewEl.status.textContent='正在启动AI后台判断...';try{const response=await fetch('/api/review/ai-judge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({review_id:reviewState.reviewId})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'AI判断任务启动失败');renderReview(result,false);if(result.ai_judgment&&result.ai_judgment.status==='处理中'){startReviewPolling()}else{reviewEl.status.textContent=(result.ai_judgment&&result.ai_judgment.message)||'AI接口等待配置。'}}catch(error){stopReviewPolling();updateAiProgress({status:'异常',message:error.message});reviewEl.status.textContent=error.message;showError(error.message)}}
